import React, { useState } from 'react';
import LandingIcon from './LandingIcon.jsx';
import { CONTACT } from './landingContent.js';

const initialState = { name: '', email: '', phone: '', message: '' };

// The public landing page does not use our own server, so it keeps working when the backend is off.
// Each enquiry is emailed by FormSubmit (formsubmit.co) to the first address in CONTACT.emails, with the
// other addresses on copy. The first-ever submission asks the owner to confirm the address by email.
const [PRIMARY_EMAIL, ...OTHER_EMAILS] = CONTACT.emails;
const FORM_ENDPOINT = `https://formsubmit.co/ajax/${PRIMARY_EMAIL}`;
const SEND_TIMEOUT_MS = 20000;
const FAIL_MESSAGE = 'Sorry, we could not send your message. Please call or email us using the details above.';

// If sending fails, the visitor can still reach us: this opens their own email app with the message filled in.
const buildMailto = ({ name, email, phone, message }) => {
  const body = `Name: ${name}\nEmail: ${email}\nPhone: ${phone}\n\n${message}`;
  return `mailto:${CONTACT.emails.join(',')}?subject=${encodeURIComponent('Scholae enquiry')}&body=${encodeURIComponent(
    body
  )}`;
};

const LandingContactForm = () => {
  const [values, setValues] = useState(initialState);
  const [honey, setHoney] = useState('');
  const [status, setStatus] = useState({ type: '', message: '', mailto: '' });
  const [sending, setSending] = useState(false);

  const handleChange = e => {
    const { name, value } = e.target;
    setValues(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async e => {
    e.preventDefault();
    setSending(true);
    setStatus({ type: '', message: '', mailto: '' });
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), SEND_TIMEOUT_MS);
    try {
      const res = await fetch(FORM_ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify({
          ...values,
          _subject: `Scholae enquiry from ${values.name}`,
          _cc: OTHER_EMAILS.join(','),
          _template: 'table',
          _captcha: 'false',
          _honey: honey,
        }),
        signal: controller.signal,
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data.success === false || data.success === 'false') {
        throw new Error(data.message || 'send failed');
      }
      setStatus({ type: 'ok', message: 'Thanks for contacting us. We will reach out to you soon.' });
      setValues(initialState);
    } catch (err) {
      setStatus({ type: 'error', message: FAIL_MESSAGE, mailto: buildMailto(values) });
    } finally {
      clearTimeout(timer);
      setSending(false);
    }
  };

  return (
    <form className="sl-form" onSubmit={handleSubmit}>
      <h3>Book a free demo</h3>
      <p>Tell us a little about your school and we will get back to you.</p>
      <label htmlFor="sl-name">Your name</label>
      <input id="sl-name" name="name" type="text" value={values.name} onChange={handleChange} required />
      <div className="sl-form-row">
        <div>
          <label htmlFor="sl-email">Email address</label>
          <input id="sl-email" name="email" type="email" value={values.email} onChange={handleChange} required />
        </div>
        <div>
          <label htmlFor="sl-phone">Phone number</label>
          <input id="sl-phone" name="phone" type="tel" value={values.phone} onChange={handleChange} />
        </div>
      </div>
      <label htmlFor="sl-msg">How can we help?</label>
      <textarea
        id="sl-msg"
        name="message"
        rows="4"
        placeholder="School name, number of students, what you are looking for..."
        value={values.message}
        onChange={handleChange}
        required
      />
      {/* Honeypot: hidden from people, filled in by spam bots. FormSubmit drops submissions where it is not empty. */}
      <input
        type="text"
        name="_honey"
        value={honey}
        onChange={e => setHoney(e.target.value)}
        tabIndex={-1}
        autoComplete="off"
        aria-hidden="true"
        style={{ position: 'absolute', left: '-9999px', width: 1, height: 1, opacity: 0 }}
      />
      <button type="submit" className="sl-btn sl-btn-primary sl-btn-block" disabled={sending}>
        {sending ? 'Sending...' : 'Send message'} <LandingIcon name="arrow" size={18} />
      </button>
      {status.message && (
        <p className={`sl-form-status sl-form-status-${status.type}`} role="status">
          {status.message}
          {status.mailto && (
            <>
              {' '}
              <a href={status.mailto}>Send it by email instead</a>
            </>
          )}
        </p>
      )}
    </form>
  );
};

export default LandingContactForm;
